app/account.css:
.account-welcome-actions{display:grid;gap:12px;margin-top:12px}
.account-welcome-note{display:flex;align-items:center;justify-content:center;gap:8px;color:#aba898;font-size:10px;margin-top:20px}
.account-dialog{background:#0b0c0b;color:#f4f1e9;border:1px solid #393a33;border-radius:18px;width:min(480px,calc(100% - 28px));max-height:90svh;padding:0;margin:auto;overflow-y:auto;box-shadow:0 35px 130px #0009;color-scheme:dark}
.account-dialog::backdrop{background:#000b;backdrop-filter:blur(8px)}
.account-dialog-inner{padding:28px 34px 25px;font-family:Arial,Helvetica,sans-serif}
.account-dialog-inner>header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:31px}
.account-dialog-inner>header>span{font:24px Georgia,serif;letter-spacing:4px}
.account-dialog-inner>header>button{padding:7px;color:#c3beaf;display:flex}
.account-form-title h2,.account-recovery-success h2{font:36px/1.14 Georgia,serif;letter-spacing:-.7px;margin:13px 0}
.account-form-title p,.account-recovery-success>p{font-size:12px;line-height:1.75;color:#aaa99d;margin:0 0 25px}
.account-form{display:grid;gap:15px}
.account-form label{display:block;font-size:11px;line-height:1.5;font-weight:400;color:#d7d4ca}
.account-form input{display:block;width:100%;padding:14px 15px;min-height:51px;background:#11130f;border:1px solid #45473d;border-radius:9px;color:#f4f1e9;font-size:14px;line-height:1.4;margin:7px 0 0;box-shadow:none}
.account-form input::placeholder{color:#909185}
.account-form input:focus{border-color:#cbb78b;outline:1px solid #cbb78b;outline-offset:0}
.account-form input:-webkit-autofill{-webkit-box-shadow:0 0 0 1000px #202219 inset;-webkit-text-fill-color:#f4f1e9}
.account-password{display:block;position:relative}
.account-password input{padding-right:50px}
.account-password>button{position:absolute;right:7px;top:4px;width:42px;height:43px;display:flex;align-items:center;justify-content:center;color:#b7b6a7}
.account-form small{font-size:10px;line-height:1.7;font-weight:400;color:#959986;display:block}
.account-form>small{margin-top:-8px}
.account-form label>small{margin-top:7px}
.account-optional{color:#929685;font-size:10px;float:right}
.account-form .account-forgot{font-size:11px;color:#d7c69e;text-align:left;width:fit-content;justify-self:start;padding:0}
.account-form .entry-primary{margin-top:6px}
.account-dialog .account-error{font-size:11px;line-height:1.7;color:#f0bdaa;background:#7b34271b;border:1px solid #7c4c3c;border-radius:8px;padding:12px;margin:0}
.account-divider{display:flex;align-items:center;gap:15px;color:#858778;font-size:8px;letter-spacing:1px;margin:24px 0 16px}
.account-divider:before,.account-divider:after{content:'';flex:1;height:1px;background:#32362b}
.account-provider{border:1px solid #45473c;border-radius:9px;min-height:48px;padding:13px 16px;display:flex;align-items:center;justify-content:center;gap:14px;color:#d8d7cb;font-size:11px}
.account-provider:hover{background:#ffffff08}
.account-provider-help{font-size:9px;text-align:center;color:#969a86;margin:10px 0 0}
.account-switch{text-align:center;font-size:11px;color:#a3a593;margin:27px 0 0;line-height:1.8}
.account-switch button{font-size:11px;color:#e1d0aa;padding:0 2px}
.account-recovery-help{font-size:10px;line-height:1.7;color:#9b9f8b;padding-top:20px}
.account-key-icon{width:48px;height:48px;border:1px solid #555341;border-radius:14px;display:flex;align-items:center;justify-content:center;margin-bottom:24px;color:#d1bd92}
.account-recovery-success code{display:block;font:13px/1.9 monospace;overflow-wrap:anywhere;background:#161910;border:1px solid #3d4530;border-radius:9px;padding:18px;color:#dfd7bc;margin-bottom:13px;user-select:all}
.account-recovery-success>small{display:block;font-size:10px;line-height:1.7;color:#a5a58d;text-align:center;margin:13px 0 25px}
.account-recovery-success .account-error{margin-bottom:14px}
.account-signout>button{display:inline-flex;align-items:center;gap:8px;font-size:10px;color:inherit;min-height:40px}
.account-signout>span{display:block;font-size:10px;line-height:1.5;color:#a34d35;max-width:150px}
.journey-header>.account-signout{color:#6a765d}
.account-dialog button:focus-visible,.account-dialog a:focus-visible{outline:2px solid #cbb78b;outline-offset:4px}
.account-dialog button:disabled{opacity:.55;cursor:wait}
@media(max-width:760px){.account-dialog{width:calc(100% - 22px);max-height:94svh;border-radius:15px}.account-dialog-inner{padding:23px 23px 26px}.account-dialog-inner>header{margin-bottom:26px}.account-form-title h2,.account-recovery-success h2{font-size:32px}.account-form input{font-size:16px}.account-welcome-actions{margin-top:0}.account-welcome-note{font-size:9px}.mandatory-login .entry-content:has(.account-welcome-actions){padding-top:20px}.journey-header>.account-signout{white-space:nowrap}}

