function StyleSettings({profile,portal,mode,action}:{profile:JourneyData['profiles'][number]|undefined;portal:PortalData;mode:JourneyMode;action:JourneyAction}){const [weights,setWeights]=useState<StyleWeights>(profile?.weights||{}),[busy,setBusy]=useState(false);return <><Heading eyebrow="YOUR PERSONAL STYLE DNA" title={mode==='buy'?'Taste changes. Make room for it.':'Let your strongest work lead.'} text="Adjust your mix. Your feed and designer matches update from these saved preferences."/><StyleMixer value={weights} onChange={setWeights} designer={mode==='design'}/><div className="onboarding-bottom"><p>Matching uses shared styles, not a certification of expertise or garment quality.</p><button className="button primary" disabled={busy||!profile||!Object.keys(normalizeWeights(weights)).length} onClick={async()=>{if(!profile)return;setBusy(true);await action({action:'styleProfile',...profile,weights:normalizeWeights(weights),brandName:portal.accounts.find(a=>a.role==='brand')?.details.brandName||''},'Your style mix has been updated.');setBusy(false);}}>Save my mix<Check size={16}/></button></div></>;}
