export function CreatorWorkspace({data,portal,onDesign,onNewPost,onMonetize,onDeletePost}:{data:Data;portal:PortalData;onDesign:(p?:Product)=>void;onNewPost:()=>void;onMonetize:()=>void;onDeletePost:(id:string)=>void}){
 const [tab,setTab]=useState('Overview');const myPosts=portal.posts.filter(p=>p.userId===data.user?.id),ids=new Set([...data.designs.map(d=>d.id),...myPosts.map(p=>p.id)]);const likes=data.reactions.filter(r=>ids.has(r.productId)).reduce((n,r)=>n+Number(r.count),0),saves=portal.saveCounts.filter(r=>ids.has(r.productId)).reduce((n,r)=>n+Number(r.count),0),shares=portal.shareCounts.filter(r=>ids.has(r.productId)).reduce((n,r)=>n+Number(r.count),0);const rows=[...data.designs.map(d=>({id:d.id,title:d.title,type:d.published?'Published design':'Draft'})),...myPosts.map(p=>({id:p.id,title:p.title,type:p.mediaType==='video'?'Reel':'Post'}))];
 return <><div className="portal-page-heading"><div><span className="eyebrow">CREATOR PORTAL</span><h1>Ideas are your currency.</h1><p>Your canvas, your community, your creative business.</p></div><div className="actions"><button className="button secondary" onClick={onNewPost}><Plus size={16}/>Create post</button><button className="button primary" onClick={()=>onDesign()}><Plus size={16}/>Open design canvas</button></div></div><div className="workspace-tabs">{['Overview','Designs & posts','Monetization'].map(t=><button key={t} className={tab===t?'selected':''} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Overview'&&<><div className="stats-grid"><Metric title="Total likes" value={likes} note="Recorded reactions"/><Metric title="Followers" value={portal.followerCount} note="Your community"/><Metric title="Saves" value={saves} note="Added to inspiration boards"/><Metric title="Shares" value={shares} note="Unique signed-in share actions"/></div><div className="dashboard-split"><div className="panel"><span className="eyebrow">YOUR WORK, IN NUMBERS</span><h2>What’s resonating.</h2><Performance rows={rows} data={data} portal={portal}/></div><div className="creator-next"><span className="eyebrow">YOUR NEXT BIG IDEA</span><h2>Start with a blank.<br/>End with a statement.</h2><p>Build with typography, graphics, uploaded artwork, and your imagination.</p><button className="button primary" onClick={()=>onDesign()}>Enter the canvas<ArrowUpRight size={17}/></button><button className="text-button" onClick={()=>setTab('Monetization')}>Explore monetization<ArrowUpRight size={16}/></button></div></div></>}{tab==='Designs & posts'&&<><div className="section-heading"><h2>Your designs</h2><span>{data.designs.length} designs · {myPosts.length} posts</span></div><div className="draft-grid">{data.designs.map(d=><article className="draft-card" key={d.id}><button onClick={()=>onDesign(d)}><Garment config={d.config}/></button><div><span className="badge">{d.published?'PUBLISHED':'DRAFT'}</span><h3>{d.title}</h3><button className="text-button" onClick={()=>onDesign(d)}>Edit design<ArrowUpRight size={14}/></button></div></article>)}</div><div className="section-heading"><h2>Your posts & reels</h2><button className="text-button" onClick={onNewPost}>New post<Plus size={16}/></button></div><div className="my-post-grid">{myPosts.map(p=><article key={p.id}>{p.mediaType==='video'?<video src={p.mediaUrl} controls playsInline preload="metadata"/>:<img src={p.mediaUrl} alt={p.title}/>}<div><h3>{p.title}</h3><p>{p.caption}</p><button className="text-button" onClick={()=>onDeletePost(p.id)}><Trash2 size={14}/>Delete post</button></div></article>)}</div>{!rows.length&&<div className="empty-state"><ImagePlus size={34}/><h3>Give your first idea a place to live.</h3><p>Create a design or upload a post to start your portfolio.</p></div>}</>}{tab==='Monetization'&&<div className="monetization-layout"><div className="panel"><span className="eyebrow">TURN CREATIVITY INTO OPPORTUNITY</span><h2>Your work has potential.</h2><p>Build your portfolio, grow a community, and register interest in print royalties or collaborations with startup brands.</p><div className="monetization-step"><span>01</span><div><strong>Create & publish</strong><p>Show customers and brands what makes your work yours.</p></div></div><div className="monetization-step"><span>02</span><div><strong>Request monetization</strong><p>Choose print royalties, brand collaborations, or both.</p></div></div><div className="monetization-step"><span>03</span><div><strong>Agree terms before earning</strong><p>Royalty rates and licensing require an agreement. Likes alone do not create earnings.</p></div></div><button className="button primary" onClick={onMonetize}>{portal.monetization?'Update your interest':'Register monetization interest'}<ArrowUpRight size={17}/></button></div><div className="earnings-card"><Wallet size={28}/><h3>Creator earnings</h3><strong>Not activated</strong><p>No royalty agreement or payout provider is connected for creators yet.</p><div className="summary-spec"><span>Application</span><b>{portal.monetization?'Interest registered':'Not submitted'}</b></div><div className="summary-spec"><span>Verified royalties</span><b>No transactions</b></div><small>Engagement metrics measure your audience. They are not a cash balance.</small></div></div>}</>;
