export function StartupWorkspace({portal,onNewProduct,onEditProduct,onFulfill,onPost}:{portal:PortalData;onNewProduct:()=>void;onEditProduct:(p:Listing)=>void;onFulfill:(p:Purchase)=>void;onPost:()=>void}){
 const [tab,setTab]=useState('Overview');const paid=portal.sales.filter(s=>s.mode==='live'&&s.paymentStatus==='paid'),gross=paid.reduce((n,s)=>n+s.amount-s.refunded,0),sold=paid.filter(s=>s.refunded===0).reduce((n,s)=>n+s.quantity,0),low=portal.ownListings.filter(l=>l.stock<5);return <><div className="portal-page-heading"><div><span className="eyebrow">STARTUP PORTAL</span><h1>Your label. Your business.</h1><p>Launch a collection, manage your inventory, and keep every order in view.</p></div><div className="actions"><button className="button secondary" onClick={onPost}><ImagePlus size={16}/>Post to the feed</button><button className="button primary" onClick={onNewProduct}><Plus size={16}/>Add product</button></div></div><div className="workspace-tabs">{['Overview','Products','Orders','Receiving'].map(t=><button className={tab===t?'selected':''} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Overview'&&<><div className="stats-grid"><Metric title="Net collected" value={money(gross)} note="Verified live payments minus refunds"/><Metric title="Units sold" value={sold} note="Verified paid, non-refunded orders"/><Metric title="Products live" value={portal.ownListings.filter(l=>l.published).length} note="Visible in customer Explore"/><Metric title="Unpaid requests" value={portal.sales.filter(s=>s.paymentStatus==='unpaid'||s.paymentStatus==='pending').length} note="Not counted as revenue"/></div><div className="dashboard-split"><div className="panel"><div className="section-heading"><h2>Your latest orders.</h2><button className="text-button" onClick={()=>setTab('Orders')}>View all<ArrowUpRight size={16}/></button></div><OrderTable orders={portal.sales.slice(0,6)} seller onFulfill={onFulfill}/></div><div className="stock-panel"><Package size={27}/><h3>A little stock check.</h3><p>{low.length?low.length+' products are below 5 units.':'Your inventory updates appear here.'}</p>{low.map(l=><button key={l.id} onClick={()=>onEditProduct(l)}><span>{l.title}</span><b>{l.stock} left</b></button>)}<button className="button secondary full" onClick={()=>setTab('Products')}>Manage inventory<ArrowUpRight size={16}/></button></div></div></>}{tab==='Products'&&<><div className="section-heading"><h2>Your ready-made collection.</h2><span>{portal.ownListings.length} products</span></div>{portal.ownListings.length?<div className="inventory-grid">{portal.ownListings.map(l=><article key={l.id}><img src={l.image} alt={l.title}/><div><span className="badge">{l.published?'LIVE':'DRAFT'}</span><h3>{l.title}</h3><p>{money(l.price)} · {l.stock} in stock</p><small>{l.sizes.join(' / ')}</small><button className="button secondary full" onClick={()=>onEditProduct(l)}>Edit product<ArrowUpRight size={15}/></button></div></article>)}</div>:<div className="empty-state"><StoreIcon/><h3>Make your collection discoverable.</h3><p>Upload product photos, set prices, sizes, shipping, and stock. Published products appear in the customer feed.</p><button className="button primary" onClick={onNewProduct}>Add your first product<Plus size={16}/></button></div>}</>}{tab==='Orders'&&<div className="panel"><h2>From checkout to doorstep.</h2><p className="panel-note">Only verified paid orders can move to processing, shipped, and delivered.</p><OrderTable orders={portal.sales} seller onFulfill={onFulfill}/></div>}{tab==='Receiving'&&<div className="receiving-page"><div className="receiving-hero"><Wallet size={30}/><span className="eyebrow">PAYMENT RECEIVING</span><h2>{money(gross)}</h2><p>Recorded net live payments after refunds. This is not your withdrawable bank balance.</p><span className="badge">{portal.paymentsReady?'CHECKOUT CONNECTED · '+portal.paymentMode.toUpperCase():'PAYMENT PROVIDER NOT ACTIVATED'}</span></div><div className="stats-grid"><Metric title="Paid orders" value={paid.length} note="Live transactions only"/><Metric title="Refunds recorded" value={money(portal.sales.filter(s=>s.mode==='live').reduce((n,s)=>n+s.refunded,0))} note="Confirmed refund events"/>